import sys, json
sys.path.insert(0, 'tmp'); sys.path.insert(0, 'submission')
import ref, main as M
doc = {"version": 1, "ixps": [45], "rib": [{"path": [168, 87, 92, 45, 45, 174], "count": 1}, {"path": [92, 174, 168, 168, 87], "count": 5}, {"path": [87], "count": 1}, {"path": [168, 92, 87, 174, 174, 45], "count": 2}, {"path": [87, 174, 168, 92, 92, 45], "count": 3}], "priors": [], "declared": [], "order": [[87, 168], [87, 174], [92, 168], [87, 92], [92, 174], [168, 174]], "queries": []}
