agg = {}
for rec in doc['rib']:
    p = M.normalize_path(rec['path'], ixset)
    if len(p) < 2 or len(set(p)) != len(p): continue
    agg[tuple(p)] = agg.get(tuple(p),0)+rec['count']
final, rounds = M.peel(list(agg.items()))
core = set()
for p in final:
    for i in range(len(p)-1): core.add(M._canon(p[i],p[i+1]))
print("core", sorted(core))
occs1 = M.collect_occurrences(final)
occs2 = ref.ref_occurrences(final)
for l in sorted(core):
    print(l, "mine:", occs1.get(l), "\n   ref:", occs2.get(l))
# graphs
vi = {l:i for i,l in enumerate(doc['order'])}
adj1 = {i:set() for i in range(len(doc['order']))}
for l, lst in occs1.items():
    for (cnt,L,R) in lst:
        for s in (L,R):
            if s[0] is not None:
                f,_ = M._convert_spec(s, vi)
                adj1[vi[l]].add(f); adj1[f].add(vi[l])
adj2 = ref.scope_graph(occs2, core)
adj2i = {vi[k]: {vi[x] for x in v} for k,v in adj2.items()}
